type record MyRecord { 
     record { float x, float y } c, 
     integer a 
  } 
  var @lazy MyRecord v_r := { 
     c := f_computeC(), 
     a := f_computeA() 
  } // not evaluated here
  v_r.c.x := f_computeX(); // first replaces field c with result of f_computeC(),
                   // then replaces field c.x with unevaluated f_computeX()
                   // field while c.y remains fixed; field a remains unevaluated

type record MyRecord {
     charstring field1, 
     charstring field2, 
     charstring field3
  }
   var MyRecord v_myList1, v_myList2, v_myList3; 
   v_myList1 := {"value1", "value2", "value3" }; // v_myList1 is completely initialized
   v_myList2 := v_myList1;  // v_myList2 is equal to {"value1", "value2", 
                               // "value3" }
   v_myList2.field1 := "missing";  // only v_myList2 value changes to
                               // {"missing", "value2", "value3" }; 
                               // v_myList1 still contains {"value1", "value2", 
                               // "value3" } after the assignment
   v_myList3.field2 := "newvalue";  // v_myList3 is partially initialized
                               // field1 and field3 remain uninitialized
   v_myList1 := v_myList3;  // v_myList1 become partially initialized,
                               // field2 has the value "newvalue"
                               // field1 and field3 are uninitialized

