// The following TTCN-3 code fragment includes
  :
  label L1; // … the definition of label L1,
  m_myVar := 2 * m_myVar;
  if (m_myVar < 2000) { goto L1; } // … a jump backward to L1,
  m_myVar2 := f_myFunction(m_myVar);
